import{_ as i,l as n,o as e,c as o,v as t,p as l,x as s,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"组相联与替换","description":"","frontmatter":{"title":"组相联与替换","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/set-associative-replace.md","filePath":"cs/set-associative-replace.md","lastUpdated":1789023840000}'),E={name:"cs/set-associative-replace.md"};function h(B,a,A,_,m,u){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="组相联与替换" tabindex="-1">组相联与替换 <a class="header-anchor" href="#组相联与替换" aria-label="Permalink to &quot;组相联与替换&quot;">​</a></h1><div class="epigraph"><p>一块可以放进一组里的若干路，冲突不再被唯一一行钉死；组满了才需要替换策略。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/direct-mapped-cache">上一课</a>用索引选定唯一行。两个块若索引相同就会互踢，哪怕 cache 里还有空行。<a href="/cs/direct-mapped-cache">局部性原理</a>并没有要求「索引相等的块不能同时热」。本课不重讲标签比较。缺口是：放宽「只能放一个位置」，并在一组多块都满时决定踢谁。本课只交出组相联与替换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接映射把冲突和容量混在一起：明明还有别的行空着，只因为索引撞了就缺失。全相联让块放任意行，比较器个数随行数线性涨，做不大。缺口是中间形态：<strong>索引选组，组内若干路并行比标签</strong>。</p><p>组满之后，新块要替换一路。随机、FIFO、LRU 给出不同的「谁最不值得留」。本课钉 LRU 的直觉（踢最久未用），不把伪 LRU 树展开成门级。</p><p><span class="marginnote">Belady 最优替换需要未来轨迹，只能当分析下界。硬件用过去近似未来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(n\\) 路组相联：cache 分成若干组，每组 \\(n\\) 块。地址的索引选组，不再选唯一行；组内 \\(n\\) 个标签并行比较。\\(n=1\\) 就是直接映射；\\(n=\\) 总块数就是全相联。</p><p>替换：缺失且组满时，按策略选一路。LRU 维护组内使用次序；命中也要更新次序。写回课才会问被踢的那路是否要写 DRAM；本课假定只读，或假定被踢块与下一层一致。</p>',10)),(e(),l(p,null,{default:s(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20SET%5B%22%E7%B4%A2%E5%BC%95%E9%80%89%E7%BB%84%22%5D%0A%20%20SET%20--%3E%20W1%5B%22%E8%B7%AF%201%20%E6%A0%87%E7%AD%BE%22%5D%0A%20%20SET%20--%3E%20W2%5B%22%E8%B7%AF%202%20%E6%A0%87%E7%AD%BE%22%5D%0A%20%20W1%20--%3E%20CMP%5B%22%E5%B9%B6%E8%A1%8C%E6%AF%94%E8%BE%83%22%5D%0A%20%20W2%20--%3E%20CMP%0A%20%20CMP%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%E4%B8%80%E8%B7%AF%22%5D%0A%20%20CMP%20--%3E%20REPL%5B%22%E7%BC%BA%E5%A4%B1%E4%B8%94%E6%BB%A1%EF%BC%9ALRU%20%E6%9B%BF%E6%8D%A2%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相联度上升，冲突缺失下降，命中时间通常上升（更多比较与 mux）。这是 CPI 里「停顿减少」对「时钟周期变长」的交易，<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a>已经准备好这项比较。常用选择是 2 路或 4 路，而不是全相联。</p><p>LRU 在相联度高时状态昂贵。教学上 2 路 LRU 只需一位。替换策略改变的是缺失率，不改变命中时的标签语义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入写分配，不讨论 inclusive/exclusive 多层 cache。也不把替换做成操作系统页置换：那是后课虚拟内存的另一套对象，尽管 LRU 直觉相同。</p><p>后课默认：cache 是组相联的；直接映射是 1 路。谈到踢块，先问组是否已满、策略是什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组相联：索引选组，组内多路比标签。</li><li>组满才替换；LRU 踢最久未用，Belady 只当界。</li><li>写回与脏位是下一课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Belady, 1966 最优替换作为分析对照。</li></ul>',8))])}const D=i(E,[["render",h]]);export{C as __pageData,D as default};
